  "Luxe cadeauverpakking · handgeschreven kaart · geen prijs op de pakbon": { en: "Luxury gift wrapping · handwritten card · no price on packing slip", fr: "Emballage cadeau de luxe · carte écrite à la main · pas de prix sur le bon de livraison" },
  "Ga naar betaling — € 249": { en: "Proceed to payment — € 249", fr: "Passer au paiement — € 249" },
  "U wordt doorgestuurd naar onze beveiligde betaalpagina. Betaling via Stripe.": { en: "You will be redirected to our secure payment page. Payment via Stripe.", fr: "Vous serez redirigé vers notre page de paiement sécurisé. Paiement via Stripe." },
  "U wordt doorverwezen naar betaling.": { en: "You are being redirected to payment.", fr: "Vous êtes redirigé vers le paiement." },
  "De betaalpagina opent in een nieuw venster. Wij bevestigen uw reservering en editienummer persoonlijk per e-mail.": { en: "The payment page opens in a new window. We confirm your reservation and edition number personally by email.", fr: "La page de paiement s'ouvre dans une nouvelle fenêtre. Nous confirmons votre réservation et votre numéro d'édition personnellement par e-mail." },
